namespace HakutaiKagami.Core.Contracts;

public sealed record TerrainAtlasState(string Anchor,string TerrainVersion);
public sealed record TerrainTile(string Node,int X,int Y){public string Id=>$"terrain:{Node}/{X}/{Y}";}

// Nationwide node coverage is synthetic. Fixed sea routes remain the only transport between islands.
public static class ContinuousWorld
{
    public const string Ruleset="continuous-world-v1";
    public const long Cell=10000,Tile=80000,Extent=400000;
    public static bool Enabled(ContractWorld w)=>w.Definitions.Ruleset==Ruleset||OfficerLoop.Enabled(w);
    public static string Version{get;}=ContractJson.CanonicalHash(new[]{NationalRoutes.Version,CoastHash(),"atlas-global-coastland-local800m-cell10m-tile80m-height-shared-v1","bounded25-tiles-local640m-path-waterbridge-staticfootprints-v1"});
    static string CoastHash(){using var s=typeof(ContinuousWorld).Assembly.GetManifestResourceStream("JapanTerrainMaskV1")!;using var m=new MemoryStream();s.CopyTo(m);return ContractJson.Hash(m.ToArray());}
    static readonly (string Id,FieldPoint Point)[] anchors=NationalRoutes.Nodes.Select(n=>{var o=NationalRoutes.Nodes.Single(x=>x.Id=="castle").Position;return(n.Id,new FieldPoint(n.Position.EastMm-o.EastMm+5000,n.Position.NorthMm-o.NorthMm+5000));}).ToArray();
    public static FieldPoint Origin(string node)=>node=="world"?new(0,0):anchors.Single(n=>n.Id==node).Point;
    public static string Nearest(FieldPoint p){double best=double.MaxValue;string id=anchors[0].Id;foreach(var n in anchors){double dx=n.Point.X-p.X,dy=n.Point.Y-p.Y,d=dx*dx+dy*dy;if(d<best){best=d;id=n.Id;}}return id;}
    public static FieldPoint Local(FieldPoint p,string node){var o=Origin(node);return new(p.X-o.X,p.Y-o.Y);}
    public static FieldPoint Point(string node,long x,long y){var o=Origin(node);return new(o.X+x,o.Y+y);}
    public static TerrainTile TileAt(FieldPoint p){var id="world";var q=p;return new(id,(int)Math.Floor(q.X/(double)Tile),(int)Math.Floor(q.Y/(double)Tile));}
    public static TerrainTile[] VisibleTiles(FieldPoint center,double span){if(span>240)return [];var t=TileAt(center);return Enumerable.Range(t.X-2,5).SelectMany(x=>Enumerable.Range(t.Y-2,5).Select(y=>new TerrainTile(t.Node,x,y))).OrderBy(t=>t.Id,StringComparer.Ordinal).ToArray();}
    static readonly HakutaiKagami.Core.World.JapanCatalog coast=ReadCoast();
    static readonly HakutaiKagami.Core.World.LandMaskIndex landIndex=new(coast.Polygons);
    static HakutaiKagami.Core.World.JapanCatalog ReadCoast(){using var f=typeof(ContinuousWorld).Assembly.GetManifestResourceStream("JapanTerrainMaskV1")??throw new InvalidDataException("Missing coarse land mask");using var m=new MemoryStream();f.CopyTo(m);return HakutaiKagami.Core.World.JapanGeography.Read(m.ToArray());}
    static readonly System.Collections.Concurrent.ConcurrentDictionary<(long,long),string> kinds=new();
    static bool InRing(HakutaiKagami.Core.World.GeoCoordinate p,HakutaiKagami.Core.World.GeoCoordinate[] ring){bool inside=false;for(int i=0,j=ring.Length-1;i<ring.Length;j=i++){var a=ring[i];var b=ring[j];if((a.LatitudeE7>p.LatitudeE7)!=(b.LatitudeE7>p.LatitudeE7)&&p.LongitudeE7<(double)(b.LongitudeE7-a.LongitudeE7)*(p.LatitudeE7-a.LatitudeE7)/(b.LatitudeE7-a.LatitudeE7)+a.LongitudeE7)inside=!inside;}return inside;}
    public static bool Land(FieldPoint p){var q=FieldWorld.ToWorld(p);var geo=HakutaiKagami.Core.World.JapanGeography.Inverse(new(q.EastMm,q.NorthMm));return landIndex.Contains(geo);}
    static long GlobalVertex(FieldPoint p){var node=Nearest(p);var q=Local(p,node);double blend=Math.Clamp((Math.Max(Math.Abs(q.X),Math.Abs(q.Y))-300000)/100000.0,0,1);double broad=(Math.Sin(p.X/450000.0)+1)*9000+(Math.Sin(p.Y/670000.0)+1)*6000;double h=(Math.Sin((q.X+120000)/95000.0)+1)*1800+(Math.Sin(q.Y/70000.0)+1)*2200;if(q.Y>120000)h+=Math.Max(0,38000-Math.Abs(q.X-180000)/3.0-Math.Abs(q.Y-230000)/4.0);if(Math.Abs(q.Y)<=20000||q.Y>=70000&&q.Y<=110000)h=0;return (long)Math.Round(h*(1-blend)+broad*blend);}
    public static long Vertex(string node,long x,long y)=>GlobalVertex(Point(node,x,y));
    public static long Height(FieldPoint p){long x=(long)Math.Floor(p.X/(double)Cell)*Cell,y=(long)Math.Floor(p.Y/(double)Cell)*Cell,fx=p.X-x,fy=p.Y-y;long a=GlobalVertex(new(x,y)),b=GlobalVertex(new(x+Cell,y)),c=GlobalVertex(new(x+Cell,y+Cell)),d=GlobalVertex(new(x,y+Cell));return fx>=fy?a+((b-a)*fx+(c-b)*fy)/Cell:a+((c-d)*fx+(d-a)*fy)/Cell;}
    public static string KindAt(FieldPoint p){long x=(long)Math.Floor(p.X/(double)Cell),y=(long)Math.Floor(p.Y/(double)Cell);if(kinds.TryGetValue((x,y),out var kind))return kind;if(kinds.Count>=65536)kinds.Clear();return kinds.GetOrAdd((x,y),c=>CellKind(new(c.Item1*Cell+Cell/2,c.Item2*Cell+Cell/2)));}
    static string CellKind(FieldPoint p){var node=Nearest(p);var q=Local(p,node);if(Math.Abs(q.X)<Extent&&Math.Abs(q.Y)<Extent){long x=(long)Math.Floor(q.X/(double)Cell),y=(long)Math.Floor(q.Y/(double)Cell);if(y is >=8 and <10&&x is not(12 or 13))return "water";if(y==0||y==-1||x is 12 or 13)return "road";if(y>=18&&x>=22)return "cliff";return y>=2&&y<7&&x>=6&&x<20?"forest":y>12?"slope":"grass";}if(!Land(p))return "water";uint seed=HakutaiKagami.Core.Appearance.SceneryAppearance.StableSeed($"land/{p.X/80000}/{p.Y/80000}");return seed%19==0?"cliff":seed%5==0?"forest":Height(p)>16000?"slope":"grass";}
    public static SceneryTriangle[] Surfaces(TerrainTile t){var list=new List<SceneryTriangle>();for(long x=t.X*8;x<(t.X+1)*8;x++)for(long y=t.Y*8;y<(t.Y+1)*8;y++){SceneryVertex V(long a,long b)=>new(Point(t.Node,a*Cell,b*Cell),Vertex(t.Node,a*Cell,b*Cell));var a=V(x,y);var b=V(x+1,y);var c=V(x+1,y+1);var d=V(x,y+1);var k=KindAt(Point(t.Node,x*Cell+Cell/2,y*Cell+Cell/2));list.Add(new(a,b,c,k));list.Add(new(a,c,d,k));}return list.ToArray();}
    static readonly Dictionary<string,SceneryObstacle[]> obstacleCache=new(StringComparer.Ordinal);
    public static SceneryObstacle[] Obstacles(string node){lock(obstacleCache){if(!obstacleCache.TryGetValue(node,out var result))obstacleCache[node]=result=BuildObstacles(node);return result.ToArray();}}
    static SceneryObstacle[] BuildObstacles(string node){var list=new List<SceneryObstacle>();void Add(string id,string kind,long x,long y,long w,long d,long h)=>list.Add(new($"{node}/{id}",kind,Point(node,x,y),Point(node,x+w,y+d),h));Add("keep","keep",-130000,-130000,18000,14000,12000);Add("west","wall",-150000,-150000,2000,50000,3500);Add("north","wall",-150000,-100000,50000,2000,3500);Add("south","wall",-150000,-150000,50000,2000,3500);Add("east-a","wall",-102000,-150000,2000,20000,3500);Add("east-b","wall",-102000,-120000,2000,20000,3500);for(int x=6;x<20;x+=2)for(int y=2;y<7;y+=2)Add($"tree:{x}/{y}","tree",x*Cell+4500,y*Cell+4500,1000,1000,10000);return list.ToArray();}
    static SceneryObstacle[] CachedObstacles(string node){lock(obstacleCache){if(!obstacleCache.TryGetValue(node,out var result))obstacleCache[node]=result=BuildObstacles(node);return result;}}
    public static bool Walkable(FieldPoint p){if(FieldWorld.Speed(KindAt(p))<=0)return false;var node=Nearest(p);foreach(var o in CachedObstacles(node)){long dx=p.X-Math.Clamp(p.X,o.Min.X,o.Max.X),dy=p.Y-Math.Clamp(p.Y,o.Min.Y,o.Max.Y);if(dx*dx+dy*dy<1000000)return false;}for(int i=-1;i<=1;i++)for(int j=-1;j<=1;j++)if(FieldWorld.Speed(KindAt(new(p.X+i*1000,p.Y+j*1000)))<=0)return false;return true;}
    public static void Deploy(ContractWorld w,string node,bool arrival=false)
    {
        w.Atlas=new(node,Version);int count=w.Region!.PerForce;w.Region=w.Region with{Active=true,Since=w.ElapsedSeconds,Tick=w.ElapsedSeconds,Hostile=false,Units=w.Region.Units.Select((u,i)=>{int g=i/count,n=i%count;if(arrival&&u.Commander!=w.PlayerControl)return u;var p=Point(node,g==0?65000+(n%3)*10000:g==1?95000+(n%3)*10000:115000+(n%3)*10000,-5000-(g==1?35000:g==2?0:0)-(n/3)*10000+(count==3?(n-1)*10000:0));return u with{Home=p,Position=p,Goal=p,RouteOrigin=p,Route=[],Phase=u.Soldiers==0?"destroyed":u.Phase=="routed"?"routed":"standing"};}).ToArray(),Sights=arrival?w.Region.Sights:[]};RegionalBattle.Sync(w);
    }
    public static ContractWorld Create(string node="castle",int count=3,bool refuses=false,bool lowMorale=false){var w=RegionalBattle.Create(count,refuses,lowMorale);w.WorldId=new("world:continuous-world-v1");w.Definitions=w.Definitions with{Id=new("scenario:continuous-world-v1"),Ruleset=Ruleset};Deploy(w,node);w.Definitions=w.Definitions with{Version=RegionalBattle.Version(w)};RegionalBattle.Sync(w);ContractValidation.Validate(w);return w;}
    public static void Enter(ContractWorld w){if(TravelWorld.Active(w)||w.Region!.Commands.Any(c=>c.Result=="in-transit")||w.Messaging.Attempts.Any(a=>a.Status==HakutaiKagami.Core.Messaging.AttemptStatus.InTransit&&RegionalBattle.Handles(w,a.MessageId)))throw new InvalidDataException("Pending travel or courier");var site=w.Locations.Single(l=>l.Actor==w.PlayerControl).Site??throw new InvalidDataException("Not at a site");Deploy(w,RegionalCampaign.Destination(w,site),true);}
    public static void Validate(ContractWorld w){if(w.Atlas==null||w.Atlas.TerrainVersion!=Version||!anchors.Any(a=>a.Id==w.Atlas.Anchor))throw new InvalidDataException("Atlas definition mismatch");foreach(var u in w.Region!.Units){if(u.Commander==w.PlayerControl&&Nearest(u.Home)!=w.Atlas.Anchor||RegionalGround.Distance(u.Home,Origin(Nearest(u.Home)))>500000)throw new InvalidDataException("Invalid atlas home");}}
}
